async function runCaptures(screenFilter?: string[]) {
  // responsive.config.ts declares one Playwright project per viewport; the spec drives the capture
  const configPath = path.join(baseDir, 'browser', 'responsive.config.ts');
  const specPath = path.join(baseDir, 'browser', 'tests', 'design-capture.spec.ts');

  // cd into the browser dir first so Playwright resolves its config, deps, and output paths from that root
  let cmd = `cd "${path.join(baseDir, 'browser')}" && npx playwright test ` +
            `"${specPath}" --config "${configPath}" --reporter=list`;
  if (screenFilter && screenFilter.length > 0) {
    // Scope the run to specific screens via an env var the spec reads — skips re-shooting the whole set
    cmd = `DESIGN_CAPTURE_SCREENS=${screenFilter.join(',')} ${cmd}`;
  }

  try {
    // 600s ceiling — a full sweep navigates and screenshots every screen at every viewport, which is slow
    execSync(cmd, { timeout: 600000, encoding: 'utf-8' });
  } catch (error: any) {
    // A screen that isn't reachable yet is expected, not fatal —
    // it just gets marked NOT_IMPLEMENTED further down the pipeline.
    // Playwright exits non-zero when ANY capture fails, so we swallow it rather than abort the report
    log(`Playwright exited with warnings: ${error.message?.slice(0, 200)}`, 'warn');
  }
}

function loadFigmaReferences(): Map<string, string> {
  const refs = new Map<string, string>();

  for (const screen of FIGMA_SCREENS) {
    // Each screen's reference PNG lives under the design source dir by its exported filename
    const sourcePath = path.join(figmaSourceDir, screen.figmaFile);

    if (fs.existsSync(sourcePath)) {
      // Copy into the report dir renamed to <screen.id>.png so matchScreens pairs by id, not export name
      const destPath = path.join(figmaDir, `${screen.id}.png`);
      fs.copyFileSync(sourcePath, destPath);
      refs.set(screen.id, destPath);
    } else {
      // No export on disk — drop the screen from the map; it'll show a live capture with nothing to diff
      log(`Missing: ${screen.figmaFile} — skipping ${screen.id}`, 'warn');
    }
  }
  return refs;
}

function matchScreens(screens: ScreenMapping[], figmaRefs: Map<string, string>,
                       viewports: readonly string[]): ScreenComparison[] {
  return screens.map(screen => {
    // null when the export was missing above — a capture with no reference to compare against
    const figmaPath = figmaRefs.get(screen.id) || null;

    const captures = viewports.map(vp => {
      // Capture filenames are <screenId>-<viewport>.png; presence on disk IS the signal — no pixel diffing
      const fullPath = path.join(capturesDir, `${screen.id}-${vp}.png`);
      const captured = fs.existsSync(fullPath);
      return { viewport: vp, screenshotPath: captured ? fullPath : null, captured };
    });

    // status stays NOT_CAPTURED until analyzeGaps classifies from the per-viewport captured flags
    return { screen, figmaPath, captures, status: 'NOT_CAPTURED', observations: [] };
  });
}

function analyzeGaps(comparisons: ScreenComparison[]) {
  for (const comp of comparisons) {
    // Three tallies drive everything: total captured, whether desktop captured, and how many mobile did
    const capturedCount = comp.captures.filter(c => c.captured).length;
    const total = comp.captures.length;
    const desktopOk = comp.captures.find(c => c.viewport === 'desktop')?.captured ?? false;
    const mobileOk = comp.captures.filter(c => c.viewport !== 'desktop' && c.captured).length;

    // Branches are checked top-down and are mutually exclusive; order encodes precedence
    if (capturedCount === 0) {
      // Nothing captured anywhere → the screen isn't reachable in this build at all
      comp.status = 'NOT_IMPLEMENTED';
      comp.observations.push('Screen not reachable in current build — no screenshots captured');
    } else if (capturedCount === total) {
      comp.status = 'MATCH';
      comp.observations.push(`Responsive: captured across all ${total} viewports`);
    } else if (desktopOk && mobileOk === 0) {
      // The signal this agent exists for: renders on desktop, on NO phone viewport → dead end for mobile
      comp.status = 'PARTIAL';
      comp.observations.push('DESKTOP-ONLY: Not available on any mobile viewport');
      addPerDeviceMissingReasons(comp, comp.captures.filter(c => !c.captured).map(c => c.viewport));
    } else {
      // Captured on some-but-not-all viewports — partial coverage, note the fraction
      comp.status = 'PARTIAL';
      comp.observations.push(`Captured in ${capturedCount}/${total} viewports`);
    }
  }
}

function buildReport(comparisons: ScreenComparison[], includeLandscape = false): ComparisonReport {
  return {
    // ISO timestamp doubles as the report filename suffix downstream, keeping successive runs side by side
    timestamp: new Date().toISOString(),
    totalScreens: comparisons.length,
    // "captured" = at least one viewport landed; distinct from MATCH, which requires ALL viewports
    captured: comparisons.filter(c => c.captures.some(cap => cap.captured)).length,
    matching: comparisons.filter(c => c.status === 'MATCH').length,
    partial: comparisons.filter(c => c.status === 'PARTIAL').length,
    notImplemented: comparisons.filter(c => c.status === 'NOT_IMPLEMENTED').length,
    includeLandscape,
    screens: comparisons,
  };
}

function generateMarkdown(report: ComparisonReport): string {
  const lines: string[] = [];
  lines.push('# Mobile Responsiveness Validation Report');
  lines.push(`**Total Screens Tested:** ${report.totalScreens}`);
  // Summary line collapses the three status buckets into the headline counts a reviewer scans first
  lines.push(`**Full Responsive:** ${report.matching}  **Partial:** ${report.partial}  ` +
             `**Not Reachable:** ${report.notImplemented}`);

  for (const comp of report.screens) {
    // Per-screen heading carries the label and its status verdict so the section is skimmable
    lines.push(`### ${comp.screen.label} — ${comp.status}`);
    // ... side-by-side image table: design picture | desktop | phone A | phone B
    // Each observation (incl. per-device missing reasons from analyzeGaps) becomes a bullet
    for (const obs of comp.observations) lines.push(`- ${obs}`);
  }
  return lines.join('\n');
}
